      "body": "서울 송파구가 풍납초등학교 주변 통학로 6곳을 고친다고 11월 20일 밝혔습니다. 모두 4억 1170만 원을 들여 내년 상반기까지 차례로 바꿀 계획입니다. 이 일은 11월 12일 학부모 간담회에서 나온 의견을 반영한 것입니다.\n\n송파구는 이달 안에 어린이 승하차구역을 정해 등하교 시간의 차량 혼잡을 줄입니다. 아파트 후문 근처에는 도로반사경을 달고, 과속방지턱도 다시 칠합니다. 다음 달까지는 폭 1.5m의 임시 보행로를 만듭니다. 내년 상반기에는 어린이보호구역을 넓히고 차량 제한 속도를 낮추는 일도 추진합니다.\n\n서강석 송파구청장은 아이들의 안전과 관련된 통학로 문제는 현장에서 답을 찾아 바로 해결하는 것이 중요하다고 말했습니다.",
