      "excerpt": "2010년 인천에서 날려 보낸 저어새가 중국 선전에서 발견됐어요. 16년째 두 나라를 오가요.",
      "body": "2010년 인천에서 다리에 가락지를 달고 자연으로 돌아간 저어새 한 마리가 중국 광둥성 선전에서 다시 사진에 찍혔습니다. 가락지 번호가 'E02'인 이 저어새는 11월 1일 밤, 선전의 한 국가급 자연보호구역 얕은 물에서 쉬고 있었습니다. 이 저어새는 16년 동안 한국과 중국을 오가며 20곳이 넘는 곳에서 관찰되었습니다.\n\n저어새는 몸길이가 75~80cm인 여름 철새입니다. 3월 말부터 7월까지 한국에서 번식하고, 겨울은 중국 남동부, 타이완, 홍콩 같은 곳에서 보냅니다. 세계에서 번식하는 저어새 가운데 90%가 넘는 수가 한국을 찾습니다. 1994년에는 세계에 350마리 남짓만 남은 것으로 여겨졌습니다. 올해 3월 홍콩조류관찰학회는 세계 동시 조사에서 역대 가장 많은 7746마리를 셌다고 밝혔습니다.\n\n권인기 인천시 저어새 생태학습관장은 저어새가 오가는 길 전체에서 보호 활동이 이뤄져야 한다고 말했습니다.",
