      "body": "칼레드 엘에나니 유네스코 사무총장이 11월 16일 캄보디아의 앙코르와트를 찾았습니다. 그는 한국의 국가유산청과 국가유산진흥원이 고치고 있는 '바칸' 보수·정비 현장을 둘러보았습니다. 현장에서는 상한 돌을 보존하는 방법과 3D로 꼼꼼하게 기록하는 과정을 살펴보았습니다.\n\n국가유산진흥원은 17일, 엘에나니 사무총장이 한국과 캄보디아의 협력 사업에 감사하고 성과를 칭찬했다고 전했습니다. 앙코르 지역은 9세기부터 15세기까지 크메르 제국의 수도였습니다. 지금도 1000개가 넘는 사원이 남아 있고, 1992년에 유네스코 세계유산이 되었습니다.\n\n국가유산청과 국가유산진흥원은 앙코르 유적을 관리하는 캄보디아의 압사라청과 함께 2027년 2월까지 바칸의 아랫부분을 고치고 정비할 계획입니다.",
