      "body": "11월 14일 서울 마곡동 LG사이언스파크에서 제14회 전국 이중언어 말하기 대회가 열렸습니다. 교육부가 2013년부터 여는 이 대회는 이주 배경을 가진 학생들이 두 언어를 잘하는 힘을 키우고, 스스로를 자랑스럽게 여기도록 돕습니다.\n\n올해는 전국 16개 시도 예선에 1118명이 참가했고, 그 가운데 58명이 본선에 올랐습니다. 학생들은 한국어와 부모님 나라의 말로 자기 이야기와 한국 문화를 좋아하는 마음을 발표했습니다. 베트남어, 중국어 등 모두 16개 언어가 쓰였습니다.\n\n제주에서는 초등학생 2명과 중학생 1명이 본선에 나가 모두 상을 받았습니다. 2명은 교육부장관상(동상)을, 1명은 특별상을 받았습니다. 오경석 제주국제교육원장은 학생들이 뿌리가 되는 언어와 문화를 존중하며 자긍심을 갖고 자라고 있음을 보여 준 성과라고 말했습니다.",
