      "body": "우주항공청과 한국항공우주연구원은 11월 18일 대전에서 누리호 5차 발사 결과를 살펴보는 회의를 열었습니다. 누리호 5호기는 10월 7일 발사되었고, 위성 15기를 싣고 우주로 갔습니다.\n\n누리호는 단을 떼어 내고 다음 단에 불을 붙이는 과정을 정해진 시간에 맞춰 해냈습니다. 그리고 목표 궤도에 들어갔습니다. 작은 위성인 큐브위성 10기 가운데 9기는 제대로 밖으로 나왔습니다. 하지만 1기는 나오지 못했습니다. 명령은 잘 내려졌지만, 위성이 든 통의 덮개를 여는 모터에 전기가 흐르지 않았습니다. 전기가 왜 흐르지 않았는지는 아직 정확히 밝히지 못했습니다.\n\n우주항공청과 항우연은 다음 발사 전에 점검을 늘리고, 전기 신호가 지나는 길을 두 겹으로 만들 계획입니다. 오태석 우주항공청장은 이번 발사에서 성과를 거뒀지만 고칠 점도 확인했다고 말했습니다.",
