      "body": "'2026 포항국제불빛축제'가 11월 19일 저녁부터 21일까지 사흘 동안 경상북도 포항에서 열립니다. 축제는 19일 송도 포항구항에서 열리는 미디어파사드 점등식으로 시작합니다. 올해 주제는 'All Light! All Good!'입니다.\n\n올해는 영일대해수욕장 중심이던 축제 공간을 해오름대교와 송도까지 넓혔습니다. 높이 50m, 지름 20m의 커다란 사일로에는 미디어아트 작품 '조수가 만나는 곳'을 비춥니다. 20일에는 영일대 해변도로에서 시민이 함께하는 '나이트카니발'이 열리고, 모두 34개 팀이 참여하는 불빛 퍼레이드도 펼쳐집니다. 마지막 날에는 한국·프랑스·일본 3개 나라 팀이 바다 위에서 국제불꽃쇼를 펼칩니다.\n\n포항시와 포항문화재단은 경찰, 소방, 해양경찰과 함께 종합상황실을 운영하고, 사람이 많이 몰릴 곳에 안전 관리 인력을 둡니다. 박용선 포항시장은 시민과 관광객 모두가 안전하고 따뜻하게 축제를 즐기길 바란다고 말했습니다.",
