      "body": "충남 예산 신암초등학교 학생들이 '제8회 예산 청소년 e스포츠 한마당' 코딩로봇 미로탈출 종목에서 1위와 3위를 차지했습니다. 신암초등학교는 이 소식을 11월 18일 밝혔습니다. 이번 대회에는 예산 지역 초등학교에서 모두 10개 팀이 참가했습니다.\n\n코딩로봇 미로탈출은 로봇이 정해진 길을 따라 목적지에 닿도록 움직임을 설계하고 제어하는 종목입니다. 상황을 분석하는 생각하는 힘과 오류를 찾아 고치는 능력, 팀원끼리의 협력이 중요합니다. 신암초에서는 'ctrl+c' 팀과 'ctrl+v' 팀이 출전했습니다. 6학년 학생 두 명으로 이루어진 'ctrl+c' 팀이 1위를, 'ctrl+v' 팀이 3위를 했습니다.\n\n우승팀의 한 학생은 친구와 함께 로봇의 움직임을 하나씩 고치며 연습한 것이 큰 도움이 됐다고 말했습니다.",
