      "body": "동주초등학교 전교 어린이회 'IB 드리머즈 2기'가 11월 17일 아침 등교 시간에 학생 벼룩시장을 열었습니다. 어린이회 학생들은 판매팀 모집부터 행사 준비, 장터 운영까지 모든 과정을 직접 맡았습니다.\n\n벼룩시장에는 미리 신청한 판매팀 12팀이 참여했습니다. 학생 400여 명이 등굣길에 장터를 찾았습니다. 참여한 학생들은 판매 수익금 가운데 10만 원을 스스로 모았습니다. 이 돈은 네팔에서 홍수 피해를 입은 주민들에게 기부하기로 했습니다. 기부금은 국제구호개발기구 월드비전을 통해 전해질 예정입니다.\n\n전교 어린이회장은 친구들과 함께 벼룩시장을 계획하고 운영해 보니 해냈다는 생각이 들어 뿌듯했다고 말했습니다.",
