      "body": "대한럭비협회는 11월 21일 인천 남동아시아드 럭비경기장에서 유소년 태그럭비 대회를 연다고 17일 밝혔습니다. 초등학생과 중학교 1학년 학생으로 이루어진 30개 팀, 약 210명이 참가합니다.\n\n태그럭비는 상대를 몸으로 막는 태클 대신, 허리에 붙인 태그를 떼어 공격을 멈추게 하는 럭비입니다. 몸이 부딪치는 일이 적어서 처음 하는 학생도, 남학생과 여학생도 함께 하기 쉽습니다.\n\n대한럭비협회는 9월부터 이번 달까지 학교에 강사를 보내 태그럭비 교실을 열었습니다. 학생들은 이곳에서 규칙과 패스, 움직이는 법을 배웠습니다. 협회는 이번 대회에서 이기고 지는 것보다 학생들의 경기 경험과 다른 학교 친구들과의 교류를 더 중요하게 여긴다고 했습니다. 경기장 밖에서는 친환경 체험 부스와 체력 측정 행사도 열립니다.",
