      "excerpt": "남극 빙하가 바다로 빨리 흘러가지 않게 붙잡던 곳이 줄고 있다는 연구가 나왔어요.",
      "body": "극지연구소는 11월 17일, 남극 빙하의 흐름을 늦추던 '브레이크'가 약해지고 있다는 연구 결과를 발표했습니다. 이 연구에는 극지연구소와 전남대, 서울대, 미국 뉴욕주립대 연구진이 함께했습니다.\n\n빙붕은 대륙의 빙하가 바다로 흘러나와 물 위에 떠 있는 커다란 얼음판입니다. 빙붕 바닥이 바닷속 언덕이나 작은 섬에 걸린 곳을 지지점이라고 합니다. 지지점은 빙하가 바다로 빨리 흘러가지 않도록 붙잡아 줍니다.\n\n연구팀은 서남극 게츠 빙붕을 위성으로 살펴봤습니다. 카니섬과 던컨섬 사이의 지지점은 2002년 이후 크게 줄었습니다. 그 주변 얼음은 2005~2007년에 1년에 약 64m씩 움직였는데, 2017~2019년에는 약 97m씩 움직였습니다. 2010년부터 2026년까지 이곳에서 줄어든 얼음은 소양강댐에 담을 수 있는 물의 10배가 넘습니다. 연구팀은 따뜻한 바닷물이 빙붕 아래를 녹였기 때문이라고 짐작했습니다.\n\n논문을 쓴 전남대 김병훈 교수는 작은 지지점 하나가 빙붕 전체의 흐름을 조절한다는 것을 보여 준 중요한 사례라고 설명했습니다.",
