      "title": "49년 날아간 보이저 1호, 빛으로 하루 걸리는 곳에 닿아요",
      "excerpt": "1977년에 떠난 우주 탐사선 보이저 1호가 지구에서 빛으로 하루 걸리는 거리에 도착해요.",
      "body": "1977년 9월에 발사된 미국 항공우주국(NASA)의 우주 탐사선 보이저 1호가 약 49년 만에 지구에서 '1광일' 떨어진 곳에 도착합니다. 1광일은 빛이 하루 동안 달리는 거리로, 약 259억 km나 됩니다. NASA는 한국 시간으로 11월 18일 오후 7시 16분쯤 보이저 1호가 이 지점에 닿을 것으로 예상했습니다. 사람이 만든 물체가 이 거리에 닿는 것은 처음입니다.\n\n이를 기념해 서울 롯데월드타워는 11월 17일 오후 7시부터 10시까지 건물을 황금빛 조명으로 밝힙니다. 매시 정각과 30분에는 약 1분 동안 불빛을 깜빡여 보이저의 약자인 'VGR'을 모스 부호로 보여 줍니다.\n\n롯데물산의 이미현 마케팅팀 리더는 \"인류의 위대한 여정을 기리는 글로벌 캠페인에 동참하게 돼 뜻깊다\"고 말했습니다. 또 서울 어디서나 보이는 조명으로 많은 사람이 역사적인 순간을 함께 나누길 바란다고 했습니다.",
