      "body": "경기도는 파주시 문산천에서 '흰수마자'가 살고 있는 것을 확인했다고 밝혔습니다. 흰수마자는 한반도에만 사는 고유종 민물고기로, 멸종위기 야생생물 Ⅰ급입니다. 모래가 깔리고 물이 흐르는 얕은 여울에서만 삽니다.\n\n경기도해양수산자원연구소는 올해 4월과 9~10월 두 번에 걸쳐 경기 북부의 하천 4곳을 조사했습니다. 4월 조사 때는 근처 다리 공사로 바닥에 펄이 두껍게 쌓여 흰수마자를 찾지 못했습니다. 하지만 가을 조사 때는 흐르는 물에 펄이 씻겨 나가 깨끗한 모래 여울이 다시 생겼고, 흰수마자가 발견되었습니다.\n\n이번 조사에서 하천 4곳에서는 모두 49종의 민물고기가 확인되었습니다. 차탄천에서는 멸종위기 야생생물 Ⅱ급인 '묵납자루'도 발견되었습니다. 김성곤 경기도해양수산자원연구소장은 하천의 생태계가 점점 건강해지고 있다는 증거라고 말했습니다.",
