      "origTitle": "육지서 떠내려온 해양폐기물 연간 10만t…KEI·KMI·KIOST 통합 해법 논의",
      "title": "강 따라 바다로 가는 쓰레기, 해마다 약 9만 5000t",
      "excerpt": "육지에서 강을 따라 바다로 흘러가는 쓰레기를 줄이려고 세 연구기관이 힘을 모아요.",
      "body": "육지에서 생겨 강을 따라 바다로 흘러가는 쓰레기 문제를 풀기 위해 세 국책연구기관이 머리를 맞댑니다. 한국환경연구원(KEI), 한국해양수산개발원(KMI), 한국해양과학기술원(KIOST)은 11월 17일 세종국책연구단지에서 함께 심포지엄을 엽니다.\n\n김충기 한국환경연구원 선임연구위원은 2009년부터 2023년까지 5대 강 권역의 자료를 분석한 결과를 발표합니다. 해마다 평균 약 9만 5000t의 쓰레기가 바다로 흘러들었고, 그 가운데 78%가량이 홍수가 잦은 6~9월에 몰렸습니다. 홍상희 한국해양과학기술원 생태위해성연구부장은 미세플라스틱 같은 플라스틱이 바다 생물에 주는 영향을 설명합니다.\n\n김홍균 한국환경연구원장은 육지에서 시작된 바다 쓰레기는 한 기관이나 부처만으로는 해결하기 어렵다고 말했습니다. 세 기관은 앞으로 바다 쓰레기를 함께 연구해 나갈 계획입니다.",
