      "body": "'마당을 나온 암탉'으로 유명한 동화작가 황선미 작가가 신작 '조상의 선물 씨앗'을 펴냈습니다. 이 책은 어른에게도 낯선 '종자 주권' 문제를 다룹니다. 종자 주권은 우리 씨앗을 스스로 지키고 쓸 수 있는 권리를 말합니다.\n\n황선미 작가는 한라봉을 비롯한 감귤 대부분이 일본 품종이라 씨앗 사용료를 내야 한다는 사실을 알고 충격을 받았다고 말했습니다. 그리고 이 문제가 무척 심각한데도 어른을 위한 정보만 있을 뿐, 아이들을 위한 설명은 없었다고 말했습니다.\n\n1963년 충청남도 홍성군에서 태어난 황선미 작가는 1995년 동화작가로 첫발을 내디뎠습니다. 작가는 동화가 아이만을 위한 것이 아니라 모두를 위한 이야기라고 말합니다. 또 어린이가 읽는다고 해서 무릎을 굽히지는 않겠다며, 어린이에게 아부하지 않는 동화를 쓰려고 애써 왔습니다.",
