      "body": "미지센터(시립청소년문화교류센터)는 11월 2일부터 7일까지 서울 청소년들의 태국 방콕 방문을 진행했다고 밝혔습니다. 이번 방문에는 서울 청소년 30명과 인솔자 5명이 참여했습니다. 방콕에서는 지난 9월 서울을 찾았던 방콕 청소년 30명이 함께했습니다.\n\n참가자들은 방콕시청을 찾아 사논 왕상분 방콕시 부시장을 만났습니다. 부시장은 청소년 교류가 자매도시인 서울과 방콕의 협력을 넓히는 계기가 될 것이라고 평가했습니다. 청소년들은 룸피니공원에서 시민들의 여가활동에 참여했습니다. 태국의 역사 유적과 전통 공연도 둘러보았습니다.\n\n미지센터는 2027년 4월 방콕 청소년들을 다시 서울로 초청할 예정입니다.",
