      "body": "충남 아산시가 11월 13일 신정호에서 '신정호 키즈가든·별빛오름길' 개장식을 열고 운영을 시작했다고 16일 밝혔습니다. 두 시설은 약 7만 1000㎡ 넓이로 만들어졌습니다. 신정호는 지난해 1월 충남 제1호 지방정원으로 등록된 곳입니다.\n\n키즈가든에는 숲모험놀이터와 트램펄린 같은 어린이 놀이시설이 있습니다. 가족이 함께 쉬어 갈 피크닉 공간도 마련했고, 누구나 무료로 이용할 수 있습니다.\n\n별빛오름길은 전망대와 스카이워크를 잇는 476m 길이의 산책로입니다. 해가 지면 길에 경관조명이 켜져 낮과는 다른 분위기를 냅니다. 오세현 아산시장은 신정호가 도심 속 휴식·문화예술·체육 공간이라고 말했습니다.",
