      "body": "서울 한성백제박물관의 서울백제어린이박물관이 11월 17일부터 2027년 3월 7일까지 특별전을 엽니다. 전시 이름은 'Dima: 아기 매머드 디마와 함께하는 빙하기 탐험'입니다. 전곡선사박물관과 함께 마련해 백제 중심이던 전시 주제를 선사시대로 넓혔습니다.\n\n'디마'는 1977년 시베리아에서 얼어붙은 채로 발견된 아기 매머드의 이름입니다. 디마는 약 4만 4500년 전에 살았습니다. 어린이들은 디마를 통해 빙하기의 자연환경과 생태를 살펴볼 수 있습니다.\n\n어린이들은 탐험 활동지를 들고 매머드 발자국을 따라 전시장을 둘러봅니다. 3부에서는 매머드가 추운 환경에서 어떻게 살아남았는지 알아보고 상아를 직접 만져 볼 수 있습니다. 김지연 한성백제박물관장은 어린이들이 먼 과거의 생명과 자연에 호기심을 키우길 바란다고 말했습니다.",
