      "body": "가격 조사 기관인 한국물가정보는 올해 4인 가족이 김장을 하는 데 드는 비용이 전통시장에서 28만8500원, 대형마트에서 36만340원이라고 발표했습니다. 작년보다 전통시장은 14.8%, 대형마트는 10.9% 줄었습니다. 전통시장 비용은 2020년대 들어 가장 낮습니다.\n\n가격이 내린 가장 큰 이유는 가을 날씨가 좋아 배추와 무, 쪽파 같은 채소가 잘 자랐기 때문입니다. 전통시장에서 배추 20포기 값은 8만원으로 33.3% 내렸고, 쪽파 값은 절반으로 떨어졌습니다. 반대로 새우젓은 바다 온도가 높아 새우를 잡기 어려워지면서 33.3% 올랐고, 천일염도 비싸졌습니다.\n\n한국물가정보는 포장김치를 사 먹는 사람이 늘면서 김장철에 사람들이 한꺼번에 재료를 사는 일이 줄어든 것도 가격 안정에 영향을 줬다고 분석했습니다. 김장하기 좋은 때는 중부 지방이 11월 하순에서 12월 초, 남부 지방이 12월 초에서 중순으로 예상됩니다.",
