      "excerpt": "대구동천초가 전국 학교예술교육 축제에서 합창과 오케스트라 두 부문 상을 받았어요.",
      "body": "대구동천초등학교가 '2026 전국 학교예술교육 축제'에서 합창과 오케스트라 두 부문 모두 교육부장관상을 받았습니다. 축제는 11월 3일부터 4일까지 서울 우리금융아트홀에서 열렸습니다. 교육부와 16개 시도교육청, 학교예술교육중앙지원단이 함께 연 행사입니다.\n\n합창 부문에서 상을 받은 예울림합창단은 전통 민요 '한강수타령'을 요즘 느낌으로 새로 꾸민 합창곡을 불렀습니다. 오케스트라 부문의 해오름오케스트라는 '아리랑랩소디'를 연주했습니다. 익숙한 우리 가락을 웅장한 오케스트라 소리로 새롭게 들려주었습니다.\n\n김우근 교장은 이번 수상이 학생들이 꾸준히 연습하며 서로 배려하고 맞춰 가며 얻은 값진 결과라고 말했습니다.",
