      "excerpt": "인기 애니메이션 '케이팝 데몬 헌터스'가 2027년 6월부터 세계 50개 도시에서 공연을 열어요.",
      "body": "넷플릭스 애니메이션 '케이팝 데몬 헌터스'가 세계를 도는 공연을 엽니다. 넷플릭스와 공연 기획사 AEG 프레젠츠는 11월 13일(현지 시간) '케이팝 데몬 헌터스 골든 월드투어' 계획을 발표했습니다. 투어는 2027년 6월 5일 미국 볼티모어에서 시작해 약 2년 동안 북미, 유럽, 아시아·태평양, 중남미의 50개 도시에서 150회 넘게 열릴 예정입니다.\n\n공연에서는 영화 속 걸그룹 헌트릭스의 루미, 미라, 조이가 첨단 영상 기술로 관객과 실시간으로 소통합니다. 라이벌 그룹 사자보이즈와 호랑이 캐릭터 더피의 애니메이션 무대, 댄서들의 라이브 공연도 펼쳐집니다. 아시아·태평양과 중남미 공연 일정은 나중에 발표됩니다.\n\n지난해 6월 공개된 이 영화는 넷플릭스에서 누적 조회 수 6억 7000만 회를 넘었습니다. 넷플릭스의 매리언 리 최고마케팅책임자는 \"'케이팝 데몬 헌터스'는 폭발적인 히트작에서 한 세대를 아우르는 문화적 현상으로 변모했다\"고 말했습니다.",
