      "body": "신라문화유산연구원이 경주 황룡사 남쪽 일대를 10년 동안 발굴한 성과를 전시로 보여 줍니다. 특별전 '황룡사 남쪽, 땅이 말해주는 왕경이야기'는 연구원 역사문화전시실에서 2027년 1월 31일까지 열립니다. 이 전시는 2015년부터 2025년까지 이 일대를 발굴한 결과를 바탕으로 마련되었습니다.\n\n발굴에서 확인된 논은 6세기 무렵 이곳이 농사짓는 땅이었음을 보여 줍니다. 그 뒤 이곳에는 황룡사와 도시가 들어섰고, 물건을 만드는 곳과 큰 광장도 생겼습니다. 공방 터에서 나온 흙과 돌로 만든 거푸집, 청동 도가니는 당시 사람들이 금속 물건을 만들었다는 것을 보여 줍니다.\n\n당나라의 백자와 청자, 로만글라스 같은 다른 나라 유물도 나왔습니다. 이 유물들은 신라의 수도가 바깥 세계와 교류했음을 보여 줍니다. 주진옥 신라문화유산연구원장은 유물에 담긴 옛사람들의 생활과 교류의 흔적을 살펴보는 기회가 되길 바란다고 말했습니다.",
