      "body": "유니세프 한국위원회가 세계 어린이의 날을 맞아 11월 19일과 20일 이틀 동안 서울 마포구 유니세프 블루홀에서 '2026 더아동페스타'를 엽니다. 올해 주제는 디지털 환경 속 어린이의 마음 건강입니다. 온라인 세상이 어린이의 감정과 친구 관계에 어떤 영향을 주는지 살펴봅니다.\n\n행사에서는 안전한 디지털 환경, 건강한 인간관계, 어린이의 선택권, 사회가 함께 지는 책임이라는 네 가지 주제를 이야기합니다. 대한민국아동총회 의장단 같은 어린이 대표도 참여하고, 행사장에는 체험 부스 5개가 운영됩니다. 현장 참가는 하루 200명씩 선착순이고 참가비는 무료이며, 온라인 생중계도 합니다.\n\n허금주 유니세프 한국위원회 사무총장은 \"디지털 공간에서 아이들이 겪는 어려움을 사회가 먼저 발견하고 함께 해결해야 한다\"고 말했습니다. 유니세프는 디지털 기기를 쓰는 시간을 줄이는 것만으로는 어린이를 보호하기 어렵고, 처음부터 안전하게 설계된 디지털 환경이 중요하다고 강조했습니다.",
