      "body": "서울 동대문구청이 11월 8일 구청 2층 다목적강당에서 '제1회 동대문구 AI·로봇 경진대회'를 열었습니다. 동대문구에 사는 초등학교 3~6학년 학생 100명이 29개 팀을 이뤄 참가했습니다. 학생들은 대회 전에 교구 쓰는 법과 경기 규칙, 안전 수칙을 미리 배웠습니다.\n\n로봇 부문에서 3~4학년은 로봇을 조립해 축구 대결을 했고, 5~6학년은 로봇팔로 화물을 나누는 과제에 도전했습니다. AI 부문에서 3~4학년은 AI로 컬러콘을 모으는 대결을, 5~6학년은 AI 미션 릴레이 경주를 펼쳤습니다. 모두 16개 팀이 구청장상을, 13개 팀이 창의상을 받았습니다.\n\n최동민 동대문구청장은 학생들이 첨단 기술을 직접 경험하고 팀워크로 문제를 해결하는 기회가 됐기를 바란다고 말했습니다. 또 앞으로도 AI와 로봇에 관심 있는 학생들을 돕겠다고 밝혔습니다.",
