      "body": "올해 말 개통할 예정이던 인천발 KTX가 결국 해를 넘기게 되었습니다. 국가철도공단은 인천발 KTX 사업 기간을 올해 12월 31일에서 내년 6월 30일까지 6개월 늘려 달라고 국토교통부에 요청했습니다. 남은 공사를 마무리하려면 시간이 더 필요하다는 판단입니다.\n\n이 사업은 수인선과 경부고속선을 잇는 3.19㎞ 길을 새로 만들고, 송도역·초지역·어천역을 넓히는 일입니다. 처음에는 2021년 개통을 목표로 했지만 여러 번 미뤄졌습니다. 낮에는 수인분당선 열차가 다녀서, 개통 전 시험 운행을 주로 밤에만 할 수 있는 것도 어려움입니다.\n\n인천발 KTX가 개통하면 송도역에서 부산까지 약 2시간 30분, 목포까지 약 2시간 10분이면 갈 수 있습니다.",
