      "body": "경기도 하남시에 12월 '하남시 어린이영어도서관'이 문을 엽니다. 하남시는 도서관을 운영할 전문 인력 8명을 새로 뽑고, 11월 9일 오리엔테이션을 열어 문 열 준비를 시작했다고 10일 밝혔습니다.\n\n새로 뽑은 8명 가운데 4명은 영어를 모국어로 쓰는 원어민 교사입니다. 하남시는 원어민 교사를 지방공무원으로 직접 뽑았습니다. 이들은 영어 그림책 읽기, 생활 영어 체험, 역할극처럼 어린이 눈높이에 맞춘 프로그램을 맡습니다.\n\n도서관은 하남시 미사강변남로에 있으며, 지하 1층부터 지상 4층까지 있는 건물입니다. 하남시는 이곳을 영어만 쓰는 공간으로 꾸며, 어린이들이 영어를 놀이처럼 자연스럽게 익히도록 할 계획입니다.",
