      "origTitle": "휴보·우리별·혼천시계…한국 과학기술 유산 23건 새로 등록",
      "title": "로봇 '휴보'와 인공위성 '우리별', 국가 과학 유산 됐어요",
      "excerpt": "휴보, 우리별, 혼천시계 등 23건이 국가중요과학기술자료로 새로 등록됐어요.",
      "body": "국립중앙과학관은 2026년 국가중요과학기술자료 23건을 새로 뽑고, 11월 10일 등록증 수여식을 연다고 밝혔습니다. 이번에 23건이 더해져 국가중요과학기술자료는 92건에서 115건으로 늘었습니다. 2019년 이 등록 제도를 만든 뒤 처음으로 100건을 넘었습니다.\n\n우리나라 첫 완성형 두 발 걷기 사람 모양 로봇인 '휴보(KHR-3)'가 이번에 등록되었습니다. 우리나라 첫 인공위성을 만들고 운영한 과정을 담은 '우리별 관련 기록물'과 '소백산천문대 61㎝ 망원경'도 들어갔습니다. 동양의 천문 기구에 서양의 시계 기술을 더한 '혼천의 및 혼천시계'도 포함되었습니다.\n\n우리나라 학자가 발견하고 이름 붙여 세계에서 인정받은 첫 새로운 광물인 '장군석 표본'도 등록되었습니다. 이은영 국립중앙과학관장은 앞으로도 우리 과학기술 발전에서 의미 있는 자료를 꾸준히 찾아 관리하겠다고 말했습니다.",
