      "body": "국립낙동강생물자원관이 국내 습지플라나리아 무리에서 신종 3종을 밝혀냈다고 11월 10일 발표했습니다. 새로 이름을 얻은 생물은 다변새망토머리플라나리아, 어리다변새망토머리플라나리아, 제주새망토머리플라나리아입니다.\n\n플라나리아는 서로 다른 종이라도 겉모습이 비슷한 경우가 많습니다. 같은 종 안에서도 무늬가 달라 눈으로 구분하기 어렵습니다. 그래서 연구진은 유전정보와 겉모습, 몸속 기관의 구조까지 함께 비교해 종의 차이를 밝혔습니다. 연구진은 2022년부터 이 연구를 이어 왔습니다.\n\n이번 신종 3종은 올해 말 국가생물종목록에 정식으로 올라갈 예정입니다. 습지플라나리아 무리가 이 목록에 들어가는 것은 처음입니다. 류시현 다양성보전연구실장은 앞으로도 아직 알려지지 않은 우리나라 생물을 찾아내겠다고 말했습니다.",
