      "body": "서울 구로구가 11월 10일 천왕근린공원에 네 번째 서울형 키즈카페를 만들고 개소식을 연다고 9일 밝혔습니다. '서울형 키즈카페 천왕근린공원점'은 날씨와 관계없이 어린이들이 뛰어놀 수 있는 구로 최초의 공원형 실내 놀이터입니다. 약 295㎡ 넓이에 네트 터널과 원통 오르기 같은 놀이시설을 갖췄습니다. 수유실과 화장실도 마련했습니다.\n\n이용할 수 있는 어린이는 서울에 살거나 서울에서 생활하는 4~9세입니다. 다른 서울형 키즈카페와 달리 초등학교 저학년도 이용할 수 있습니다. 11일부터 25일까지는 시간을 줄여 임시로 운영합니다. 예약은 서울시 우리동네키움포털에서 할 수 있습니다.\n\n장인홍 구청장은 앞으로도 안전하고 쾌적한 공공 놀이시설을 운영하겠다고 말했습니다.",
