      "body": "내년(2027년)에 초등학교에 들어가는 1학년 학생 수가 처음으로 30만 명 아래로 내려갈 것으로 보입니다. 올해 초등학교 입학생은 30만1442명으로, 1964년 통계를 내기 시작한 뒤 가장 적었습니다. 내년 입학생들이 태어난 2020년에는 아기가 27만2337명 태어나, 그 전해보다 3만 명 넘게 줄었습니다.\n\n초등학교 입학생이 가장 많았던 해는 1968년으로, 105만 명이 넘었습니다. 내년 입학생이 27만 명 안팎이 되면 그때의 약 4분의 1 수준이 됩니다. 2017년과 비교해도 9년 동안 약 15만8000명이 줄었습니다.\n\n기사는 농어촌과 지방 중소도시에서는 학생을 모으기가 더 어려워질 수 있다고 전했습니다. 다만 학교를 합치는 일은 학생 수만으로 정하기 어려우니 신중하게 결정해야 한다는 지적도 함께 실었습니다.",
