      "body": "세계기상기구(WMO)가 11월 9일 기후 현황 보고서를 내놓았습니다. 보고서는 2026년이 기록이 남아 있는 해 가운데 가장 더운 네 해 안에 들 것이라고 밝혔습니다. 2015년부터 2026년까지 12년은 기록상 가장 따뜻한 12년이 될 것으로 보았습니다.\n\n올해 1월부터 9월까지 지구의 평균 표면 온도는 산업화 이전보다 약 1.47도 높았습니다. 엘니뇨는 8월부터 강해졌고, 12월에는 역대 가장 강해질 것으로 예상됩니다. 엘니뇨는 바다의 열을 내보내 폭염과 가뭄, 큰비가 생길 위험을 높입니다.\n\n전 세계 평균 해수면은 인공위성으로 관측을 시작한 1993년 이후 가장 높아졌습니다. 7월까지 모은 자료를 보면 바닷속에 쌓인 열도 10년째 최고 기록을 세우고 있습니다.",
