      "excerpt": "제31차 유엔기후변화협약 당사국총회(COP31)가 11월 9일 튀르키예 안탈리아에서 열려요.",
      "body": "지구가 뜨거워지는 기후 위기에 함께 대응하기 위한 국제회의인 제31차 유엔기후변화협약 당사국총회(COP31)가 11월 9일 튀르키예 안탈리아에서 막을 올립니다. 이 회의는 1995년 독일 베를린에서 처음 열린 뒤 해마다 열리고 있으며, 이번에는 약 10만 명이 참석할 것으로 예상됩니다. 우리나라도 김성환 기후에너지환경부 장관을 대표로 정부대표단을 보냅니다.\n\n이번 회의에서는 석탄과 석유 같은 화석연료 사용을 줄이는 방법과, 기후 변화로 피해를 입는 개발도상국을 돕는 돈을 어떻게 마련할지가 중요하게 다뤄집니다. 인공지능(AI) 데이터센터가 전기를 많이 쓰면서 생기는 환경 문제도 논의될 것으로 보입니다.\n\n전의찬 세종대 석좌교수는 \"선진국들이 명확한 부담 규모를 제시하기를 꺼리고 있다\"며 돈을 마련하는 방안에 합의하기가 쉽지 않을 것이라고 내다봤습니다. 시민단체들은 우리나라가 온실가스를 더 많이 줄이겠다는 목표를 세워야 한다고 요구했습니다.",
