      "body": "중국에서 온 자이언트판다 두 마리가 11월 6일(현지 시간) 미국 조지아주 애틀랜타 동물원에서 처음으로 관람객을 만났습니다. 수컷 '핑핑'과 암컷 '푸솽'으로, 둘 다 올해 6살입니다. 두 판다는 9월 27일 애틀랜타에 도착해 그동안 새 환경에 적응하는 시간을 가졌습니다.\n\n애틀랜타에서 판다를 볼 수 있게 된 것은 2024년 원래 있던 판다 네 마리가 중국으로 돌아간 뒤 약 2년 만입니다. 핑핑과 푸솽은 중국 청두에 있는 판다 번식연구기지에서 태어났고, 10년 동안 애틀랜타에 머물기로 했습니다. 지금 미국에서 판다를 기르는 동물원은 애틀랜타, 워싱턴DC, 샌디에이고의 세 곳입니다.\n\n판다를 보려고 여행 일정을 하루 늘렸다는 8살 레이철 서덜랜드는 \"내 인생에서 가장 최고의 순간\"이라고 말했습니다. 셰펑 주미 중국대사는 두 판다가 건강하게 자라 판다를 사랑하는 모든 사람에게 기쁨을 주기를 바란다고 말했습니다.",
