      "body": "기상청은 11월 8일 오전 10시쯤 서울과 인천, 경기 북부에서 빗방울이 떨어지거나 눈이 날리는 것이 관측됐다고 밝혔습니다. 서울의 첫눈은 작년 12월 4일보다 26일 빨랐고, 평년 첫눈 날짜인 11월 20일보다도 12일 빨랐습니다.\n\n서울의 첫눈은 종로구 송월동에 있는 서울기상관측소에서 눈이 관측된 날을 기준으로 정합니다. 이날 눈은 약하게 내려서 쌓이지는 않을 것으로 예상됐습니다.\n\n기상청은 경기 북동부와 강원 내륙·산지를 중심으로 내린 비나 눈이 얼어 도로에 살얼음이 생기는 곳이 있을 것이라며 교통안전에 주의해 달라고 당부했습니다.",
