      "body": "서울 강동구가 어린이보호구역을 운전자 눈에 더 잘 띄게 정비했다고 11월 5일 밝혔습니다. 강동구는 서울 성내초등학교 등 40개 어린이보호구역에서 모두 1만 1273㎡ 넓이의 미끄럼 방지 포장을 새로 고쳤습니다.\n\n어린이보호구역이 시작되는 곳을 알리는 교통안전표지 23개는 불빛이 나는 LED 표지판으로 바꿨습니다. 횡단보도처럼 차도와 보도가 만나는 곳에 세운 볼라드 84개도 정비했습니다. 볼라드는 차가 보도로 들어오지 못하게 막는 짧은 기둥입니다.\n\n강동구는 어린이집과 학원 2곳을 어린이보호구역으로 새로 정하고, 초등학교 3곳은 보호구역을 더 넓히고 있습니다. 이수희 강동구청장은 앞으로도 어린이보호구역과 통학로를 세심하게 살피겠다고 말했습니다.",
