      "body": "대한빙상경기연맹은 '2026-2027 국제빙상연맹(ISU) 쇼트트랙 월드투어 3차 대회'가 11월 20일부터 22일까지 사흘 동안 서울 목동아이스링크에서 열린다고 밝혔습니다. 최민정, 김길리 선수를 비롯한 우리나라 선수들이 안방에서 팬들을 만납니다.\n\n이번 서울 대회는 이번 시즌 월드투어의 세 번째 대회입니다. 시즌 중반에 접어든 선수들의 실력과 순위 경쟁을 확인할 수 있는 무대가 될 것으로 보입니다. 21일과 22일에는 케이팝과 함께하는 공연도 열립니다.\n\n국가대표 은퇴 뜻을 밝힌 최민정 선수는 1·2차 월드투어에서 금메달 2개, 은메달 4개, 동메달 1개를 땄습니다. 지난 시즌 동계올림픽에서 금메달을 딴 김길리 선수도 이번 대회에 나섭니다.",
