      "body": "국가유산청은 '한지문화'가 유네스코 인류무형유산 평가에서 '등재 권고' 판정을 받았다고 11월 5일 밝혔습니다. 한지문화는 한지를 만드는 기술과 이를 둘러싼 공동체 문화를 함께 이르는 말입니다.\n\n한지는 닥나무와 식물성 잿물 같은 천연 재료를 씁니다. 그리고 한국 고유의 '외발뜨기' 기술로 만드는 전통 종이입니다. 장인의 기술뿐 아니라 마을 주민들이 품앗이로 함께 일하는 것도 중요한 부분입니다.\n\n최종 등재 여부는 11월 30일부터 12월 5일까지 중국 샤먼에서 열리는 정부간위원회에서 결정됩니다. 등재가 확정되면 우리나라의 인류무형유산은 23개에서 24개로 늘어납니다.",
