      "body": "시각장애인을 위한 한글 점자인 '훈맹정음'이 올해로 반포 100주년을 맞았습니다. 훈맹정음은 1926년 송암 박두성 선생이 제자들과 함께 몰래 연구해 발표했으며, '눈먼 이를 가르치는 바른 소리'라는 뜻입니다. 정부는 2020년 훈맹정음이 반포된 11월 4일을 '한글 점자의 날'로 정했습니다.\n\n문화체육관광부와 한국시각장애인연합회는 11월 4일 서울 마포구 누리꿈스퀘어에서 기념식을 열고, 한글 점자 발전에 힘쓴 사람들에게 상을 줍니다. 11월 5일과 6일에는 인천에서 여러 나라 전문가 약 150명이 모여 점자의 미래를 이야기하는 국제학술대회도 열립니다. 전국의 점자도서관과 점자교육원에서도 체험 행사가 마련됩니다.\n\n최휘영 문화체육관광부 장관은 \"한글 점자는 시각장애인의 읽고 쓸 권리를 보장하고, 그들에게 배움과 소통의 길을 열어 준 소중한 문자\"라고 말했습니다.",
