      "body": "미국 항공우주국(NASA)이 11월에 관측하기 좋은 밤하늘 현상을 소개했습니다. 11월 17일부터 18일 새벽까지는 사자자리 유성우가 가장 많이 떨어집니다. 조건이 좋으면 한 시간에 별똥별을 15개쯤 볼 수 있고, 달이 진 뒤 해 뜨기 전에 보는 것이 좋습니다.\n\n11월 15일과 16일 새벽에는 해 뜨기 전 남동쪽 하늘에서 화성과 목성이 아주 가깝게 붙어 보입니다. 하지만 두 행성이 실제로 가까워지는 것은 아니고, 지구에서 바라보는 방향이 비슷해져서 그렇게 보이는 것입니다.\n\n11월 24일에는 평소보다 크고 밝게 보이는 슈퍼문이 뜹니다. NASA는 12월과 2027년 1월까지 세 번 연달아 슈퍼문이 뜰 것이라고 내다봤습니다.",
