      "title": "11월 6일부터 '2026 원주그림책페스티벌'이 열려요",
      "excerpt": "원주 남산골문화센터에서 공존과 환대를 주제로 한 그림책 축제가 열려요.",
      "body": "강원 원주시가 주최하는 '2026 원주그림책페스티벌'이 11월 6일부터 29일까지 남산골문화센터에서 열립니다. 올해 주제는 '새로운 독자, 환대의 노래'입니다. 어린이와 어른, 여러 언어와 문화, 동물과 식물이 함께 어울려 사는 가치를 그림책으로 전할 계획입니다.\n\n주제 전시에는 알프레도 소데르기트, 권정민, 조오, 한성민 작가가 참여합니다. 알프레도 소데르기트 작가는 우루과이 몬테비데오에서 활동하는 작가입니다. 원주와 몬테비데오는 모두 '유네스코 문학 창의도시'입니다.\n\n어린이들이 참여한 '작은시민 그림책상' 기록 전시와 시민이 만든 작품을 소개하는 '모두의 그림책'도 열립니다. 11월 27일에는 '제11회 원주그림책포럼'이 그림책도서관 상상누리에서 열립니다.",
