      "excerpt": "올해 대한민국 그림책상 대상은 전미화 작가와 김지원 작가가 받았어요.",
      "body": "문화체육관광부와 한국출판문화산업진흥원은 '2026 대한민국 그림책상' 수상작 9편을 뽑았다고 11월 3일 밝혔습니다. 대상 2편, 특별상 6편, 신인상 1편입니다. 2023년에 생겨 올해 네 번째를 맞은 이 상에는 모두 506편이 응모했습니다.\n\n지어낸 이야기를 담은 픽션 부문 대상은 전미화 작가의 '바다 안 물고기에게 하늘 안 새에게 숲 안 동물에게 그리고 인간에게'가 받았습니다. 정보를 담은 논픽션 부문 대상은 김지원 작가의 '지렁이 키우지렁'입니다. 김지원 작가는 직접 지렁이를 키운 경험에 지렁이의 몸 구조와 먹이 같은 정보를 더해 이 책을 만들었습니다.\n\n대상을 받은 작가는 각각 문체부 장관상과 상금 1500만 원을 받습니다. 신인상은 여서윤 작가의 '너에게 들려주고 싶은 노래가 있어'가 받았습니다. 수상작은 볼로냐아동도서전 같은 해외 도서전을 통해 다른 나라에도 소개될 예정입니다.",
