      "excerpt": "하얀 겨울 철새 고니가 11월 '이달의 멸종위기 야생생물'로 뽑혔어요.",
      "body": "기후에너지환경부는 겨울 철새 고니를 11월 '이달의 멸종위기 야생생물'로 뽑았다고 11월 3일 밝혔습니다. 고니는 멸종위기 야생생물 Ⅰ급입니다.\n\n고니는 몸길이가 120~150cm, 몸무게가 3.4~7.8kg이나 되는 큰 물새입니다. 다 자라면 암컷과 수컷 모두 온몸이 하얗고, 검은 부리가 시작되는 곳에 노란 무늬가 있습니다. 생김새가 비슷한 큰고니보다 몸집이 작고 부리의 노란 부분이 좁습니다.\n\n고니는 유라시아 북부와 알래스카, 캐나다 북부에서 새끼를 낳고, 우리나라와 중국, 일본 등에서 겨울을 납니다. 새끼는 첫 겨울을 부모와 함께 보내며 이동하는 길과 먹이를 찾는 곳을 익힙니다.\n\n하지만 갯벌과 습지가 메워지고 개발되면서 먹이터와 쉼터가 줄었습니다. 그래서 우리나라를 찾는 고니도 예전보다 크게 줄었습니다. 기후변화로 고니가 새끼를 낳는 북극 툰드라의 환경이 바뀌는 것도 위협이 됩니다.",
