      "body": "국가데이터처는 11월 3일 '2026년 10월 소비자물가동향'을 발표했습니다. 10월 소비자물가는 1년 전 같은 달보다 2.8% 올랐습니다. 9월의 2.9%보다 조금 낮아져, 두 달 연속 오름세가 느려졌습니다.\n\n농산물 값은 1년 전보다 7.5% 내렸고, 그 가운데 채소류는 11.2% 내렸습니다. 하지만 축산물은 4.8%, 수산물은 5.4% 올랐습니다.\n\n석유류는 1년 전보다 14.9% 올라 전체 물가 상승률을 0.56%포인트 끌어올렸습니다. 경유는 19.7%, 휘발유는 11.6% 올랐습니다. 올해 1~10월을 모두 합쳐 본 소비자물가 상승률은 2.7%입니다.",
