      "body": "한국금융인재개발원 사회금융교육센터가 '2026년 금융소외지역 찾아가는 금융학교'를 진행하고 있습니다. 이번 교육은 충청남도 천안시 읍·면·리에 있는 초등학교 12곳과 중학교 1곳에서 열립니다. 모두 534명의 학생이 금융교육을 받게 됩니다.\n\n초등학생은 '돈을 다스리는 힘, 용돈관리와 금융의 기초'를 주제로 배웁니다. 돈의 흐름을 살펴보고 합리적인 소비를 공부합니다. 중학생은 금융골든벨로 금융 기초용어를 익힙니다. 모의투자 게임으로는 분산투자가 왜 중요한지 체험합니다.\n\n센터는 금융교육에서 소외되는 지역이 없도록 전국으로 찾아가는 금융교육을 하고 있습니다. 이달에는 제주 지역 청소년을 위한 금융골든벨도 열 예정입니다.",
