      "body": "한국과 중국의 청년들이 중국 산둥성 웨이팡에서 함께 연을 만들고 날렸습니다. 두 나라 청년들이 완성한 연 840개는 대규모 연 공동 제작 부문에서 기네스 세계기록으로 인정받았습니다. 신한대학교 학생과 교직원 1000여 명은 배를 타고 서해를 건너 웨이팡을 찾았습니다.\n\n10월 30일 행사에서 두 나라 청년들은 체육관에 모여 연을 조립했습니다. 그리고 빈하이 국제 연날리기 행사장에서 함께 만든 연을 가을 하늘에 띄웠습니다. 참가자들은 말이 달라도 손을 맞춰 연을 완성하며 가까워졌습니다. 한복 패션쇼와 태권도 시범으로 서로의 문화도 나누었습니다.\n\n이번 교류의 중요한 주제는 유엔 지속가능발전목표였습니다. 반기문 전 유엔 사무총장은 지속가능한 미래를 만드는 데 청년들이 맡아야 할 역할을 강조했습니다. 두 나라 청년 대표들은 기후위기에 함께 대응하겠다는 '웨이팡 이니셔티브'를 선언했습니다.",
