      "body": "국립경주문화유산연구소와 동국대학교 WISE캠퍼스가 함께 발굴한 성과를 소개하는 특별전 '같이 발굴, 가치 전시'가 11월 3일 문을 엽니다. 전시는 2027년 5월 30일까지 이어집니다.\n\n이번 전시의 주인공은 발굴 현장에 직접 참여한 동국대 WISE캠퍼스 학생들입니다. 학생들이 발굴하면서 쓴 기록과 실습 수첩을 볼 수 있습니다. 경주 구황동 지석묘(고인돌)와 신라 무덤인 쪽샘 K170호에서 나온 유물도 함께 공개됩니다.",
