      "body": "2026 아이치·나고야 아시안패러게임이 7일 동안의 경기를 마치고 10월 24일 일본 나고야에서 막을 내렸습니다. 아시안패러게임은 장애가 있는 선수들이 겨루는 아시아의 큰 스포츠 대회입니다. 우리나라는 금메달 29개, 은메달 38개, 동메달 33개 등 모두 100개의 메달을 따 종합 5위에 올랐습니다. 목표로 했던 금메달 21개보다 많았습니다.\n\n탁구의 윤지유 선수는 여자 단식, 혼합 복식, 여자 복식에서 모두 우승해 3관왕에 올랐습니다. 육상의 장민호 선수는 400m에서 세계신기록을 세우며 2관왕이 되었습니다.\n\n일본에서 처음 열린 이번 대회에는 45개 국가패럴림픽위원회에서 약 4000명이 참가해 18개 종목에서 겨뤘습니다. 마지드 라셰드 아시아패럴림픽위원회 위원장은 선수들이 이 대회의 심장이자 영혼이라고 말했습니다. 다음 대회는 2030년 카타르 도하에서 열립니다.",
