      "body": "12년 만에 제주에서 열린 제107회 전국체육대회가 7일 동안의 경기를 마치고 10월 22일 막을 내렸습니다. 10월 16일부터 열린 이번 대회에는 전국 17개 시·도와 해외에 사는 한국인 체육 단체의 선수단 등 3만여 명이 참가해 50개 종목에서 겨뤘습니다.\n\n경기도가 5년 연속 종합 우승을 차지했고, 경상북도와 서울특별시가 2위와 3위를 했습니다. 대회를 연 제주 선수단은 시범 경기를 포함해 메달 140개를 따서 목표였던 130개를 넘었습니다.\n\n대회 최우수선수(MVP)로는 체조에서 금메달 4개, 은메달 1개, 동메달 1개를 딴 여서정 선수가 뽑혔습니다. 체조 선수가 전국체전 최우수선수에 오른 것은 2012년 이후 14년 만입니다.",
