      "excerpt": "충남 서산 천수만에 겨울 철새가 10만 마리 넘게 찾아와 철새 축제가 열려요.",
      "body": "충청남도 서산시의 천수만에 겨울 철새가 10만 마리 넘게 찾아왔습니다. 서산시에 따르면 10월 20일을 기준으로 천수만에 날아온 겨울 철새는 10만 마리가 넘습니다. 여러 종류의 기러기를 비롯해 황오리, 노랑부리저어새, 쇠오리 같은 새들이 관찰되었습니다.\n\n서산시는 10월 24일부터 25일까지 이틀 동안 서산버드랜드와 천수만 일대에서 '서산버드랜드 철새기행전'을 엽니다. 정해진 시간 안에 철새를 몇 종류나 관찰했는지 겨루는 '천수만 탐조대회'가 대표 행사입니다. 천수만의 자연과 철새를 그리는 그림 그리기 대회도 열립니다.\n\n축제가 끝난 뒤에도 11월 한 달 동안 주말마다 철새를 가까이에서 볼 수 있는 탐조 투어가 운영됩니다. 심영복 서산버드랜드사업소장은 방문객들이 안전하고 즐겁게 행사를 즐길 수 있도록 최선을 다하겠다고 말했습니다.",
