      "excerpt": "일본이 화성의 위성 포보스의 흙과 돌을 가져올 탐사선 MMX를 우주로 보냈어요.",
      "body": "일본이 화성의 위성 포보스에서 흙과 돌을 가져오는 탐사선을 우주로 보냈습니다. 일본 우주항공연구개발기구(JAXA)는 10월 20일 오전 4시 41분 가고시마현 다네가시마 우주센터에서 H3 로켓에 '화성 위성 탐사선(MMX)'을 실어 발사했습니다. 발사 약 1시간 뒤 탐사선은 로켓에서 잘 떨어져 나왔습니다. 성공하면 화성의 위성에서 시료를 가져오는 첫 임무가 됩니다.\n\nMMX는 2027년 8월 화성 궤도에 도착해, 화성의 두 위성 가운데 더 크고 화성에 가까운 포보스를 조사합니다. 프랑스와 독일이 함께 만든 작은 로버 '이데픽스'가 약 100일 동안 포보스 표면을 살피며 시료를 모을 곳을 찾습니다. 탐사선은 흙과 돌을 10g 넘게 모아 2031년 지구로 돌아오는 것을 목표로 합니다.\n\n이번 탐사는 화성의 두 위성이 어떻게 생겼는지 밝히는 데 초점을 맞춥니다. 큰 천체가 화성과 부딪친 뒤 남은 조각이 위성이 되었다는 생각과, 소행성이 화성의 중력에 붙잡혔다는 생각이 맞서고 있습니다.",
