      "body": "올해 노벨 생리의학상은 '광유전학'을 개척한 세 과학자에게 돌아갔습니다. 미국 스탠퍼드대의 칼 다이서로스 교수, 독일 훔볼트대의 페터 헤게만 교수, 독일 뷔르츠부르크대의 게오르크 나겔 교수입니다. 헤게만 교수와 나겔 교수는 녹조류가 빛을 느낄 때 푸른빛을 받으면 열리는 단백질 '채널로돕신'을 밝혀냈습니다. 다이서로스 교수는 이 단백질을 신경세포에 써서 빛으로 뇌의 신경세포를 켜고 끄는 길을 열었습니다.\n\n노벨 물리학상은 미국 위스콘신대 매디슨의 프랜시스 핼전 교수가 받았습니다. 핼전 교수는 남극의 약 1㎦ 크기 얼음 속에 5000개가 넘는 빛 센서를 넣은 관측 장치 '아이스큐브(IceCube)'를 현실로 만들었습니다. 이 장치는 중성미자가 물질과 부딪칠 때 생기는 희미한 빛을 잡아냅니다. 중성미자는 다른 물질과 거의 부딪치지 않아 '유령 입자'로 불립니다.\n\n마크 피어스 노벨 물리학위원회 위원장은 핼전 교수의 끈기가 새로운 천문학으로 가는 길을 열었다고 평가했습니다.",
