      "body": "국립과천과학관은 10월과 11월 두 달 동안 '레트로 & 퓨처(Retro & Future)'를 주제로 가을 과학 문화 프로그램을 운영합니다. 레트로는 옛날 느낌, 퓨처는 미래라는 뜻입니다. 개천절, 한글날, 핼러윈, 과학관 개관 기념일 등에 맞춘 특별 프로그램도 마련했습니다.\n\n10월 3일부터 18일까지는 '레트로 퓨처 페스티벌'이 열립니다. '무궁화꽃이 피었습니다', '딱지치기' 같은 옛날 놀이와 'AI 모션 스포츠', 'AR 전시장 투어 미션' 같은 새로운 체험을 함께 즐길 수 있습니다. 한글날 무렵에는 '한글날 특별 관측회'와 '자개 한글 키링' 만들기 체험이 열립니다.\n\n11월 14일 과학관 개관 기념일에는 'AI 신과거제 현장 본선' 등 기념 프로그램이 열립니다. 11월 24일에는 새로 고친 첨단기술관과 과학탐구관이 처음 문을 엽니다.",
